import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const c="/ascendc.github.io/assets/reg_gatherb.Lxf7nviS.png",g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Reg矢量计算","link":"/api/SIMD-API/basic_api/reg_vector_compute/reg_vector_compute"},{"text":"Reg数据搬入","link":"/api/SIMD-API/basic_api/reg_vector_compute/reg_data_load/reg_data_load"},{"text":"离散搬入（GatherB）","link":"/api/SIMD-API/basic_api/reg_vector_compute/reg_data_load/GatherB_discrete"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/reg_vector_compute/reg_data_load/GatherB_discrete.md","filePath":"api/SIMD-API/basic_api/reg_vector_compute/reg_data_load/GatherB_discrete.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),t={name:"api/SIMD-API/basic_api/reg_vector_compute/reg_data_load/GatherB_discrete.md"};function e(d,s,i,o,r,h){return n(),p("div",null,[...s[0]||(s[0]=[l('<div><article class="markdown-body"><h1>离散搬入（GatherB）<span id="ZH-CN_TOPIC_0000001955999929"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/reg_compute/kernel_reg_compute_datacopy_intf.h&quot;</code>。</p><p>该指令会根据索引值index将源操作数按DataBlock（32B）收集到目的操作数dstReg中。收集过程如图1所示：</p><p><strong>图 1</strong> GatherB功能说明</p><p><img src="'+c+`" alt="图1 GatherB功能说明"></p><p>其中，index中仅前8个元素有效，每个元素对应一个DataBlock。例如，第一个元素为96（3 * 32），表示选取DataBlock3写入dstReg中对应的位置。</p><p>以下Python代码用于等价描述GatherB的数据选择过程。其中，<strong>baseAddr列表中的每个元素表示一个DataBlock</strong>，index中的元素表示相对于baseAddr的字节偏移。</p><div class="code-block"><div class="code-header"><span class="lang-label">Python</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">def</span><span class="w"> </span><span class="nf">gather_b</span><span class="p">(</span><span class="n">base_addr</span><span class="p">,</span> <span class="n">index</span><span class="p">):</span>
    <span class="n">data_block_size</span> <span class="o">=</span> <span class="mi">32</span>
    <span class="n">dst_reg</span> <span class="o">=</span> <span class="p">[]</span>
    <span class="k">for</span> <span class="n">offset</span> <span class="ow">in</span> <span class="n">index</span><span class="p">[:</span><span class="mi">8</span><span class="p">]:</span>
        <span class="n">data_block_id</span> <span class="o">=</span> <span class="n">offset</span> <span class="o">//</span> <span class="n">data_block_size</span>
        <span class="n">dst_reg</span><span class="o">.</span><span class="n">append</span><span class="p">(</span><span class="n">base_addr</span><span class="p">[</span><span class="n">data_block_id</span><span class="p">])</span>
    <span class="k">return</span> <span class="n">dst_reg</span>
</code></pre></div><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">DefaultType</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">S</span><span class="o">&gt;</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">GatherB</span><span class="p">(</span><span class="n">U</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">baseAddr</span><span class="p">,</span><span class="w"> </span><span class="n">S</span><span class="o">&amp;</span><span class="w"> </span><span class="n">index</span><span class="p">,</span><span class="w"> </span><span class="n">MaskReg</span><span class="o">&amp;</span><span class="w"> </span><span class="n">mask</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>目的操作数和源操作数的数据类型。支持的数据类型请参考<a href="#%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B">数据类型</a>。</td></tr><tr><td>U</td><td>目的操作数的RegTensor类型。例如RegTensor&lt;half&gt;，由编译器自动推导，用户不需要手动填写。</td></tr><tr><td>S</td><td>索引值的RegTensor类型，例如RegTensor&lt;uint32_t&gt;，由编译器自动推导，用户不需要手动填写。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstReg</td><td>输出</td><td>目的操作数，类型为<a href="../register_data_types/RegTensor.html">RegTensor</a>。</td></tr><tr><td>baseAddr</td><td>输入</td><td>源操作数，UB中的基地址，需要32字节对齐。</td></tr><tr><td>index</td><td>输入</td><td>索引值，dstReg中的每个DataBlock在Unified Buffer（UB）中相对于baseAddr的位置，仅前8个元素有效。单位：字节。类型为<a href="../register_data_types/RegTensor.html">RegTensor</a>。索引值必须32B对齐，即一个索引值对应1个DataBlock。index中的值可以重复。例如：<br>baseAddr: [DataBlock0, DataBlock1, DataBlock2, DataBlock3, DataBlock4, DataBlock5, DataBlock6, DataBlock7, ... , DataBlock32, ...]。<br>index: [0*32, 1*32, 2*32, 3*32, 4*32, 5*32, 6*32, 32*32]<br>dstReg: [DataBlock0, DataBlock1, DataBlock2, DataBlock3, DataBlock4, DataBlock5, DataBlock6, DataBlock32]。</td></tr><tr><td>mask</td><td>输入</td><td>DataBlock搬运的有效指示，按b32格式解释。一个DataBlock对应4bit，仅每4bit中的最低位有效。由于index仅前8个元素有效，因此mask仅使用前8个b32元素对应的bit 0、4、8、12、16、20、24、28，分别控制dstReg中DataBlock0至DataBlock7是否更新，其余bit无效。详细说明请参考<a href="../register_data_types/MaskReg.html">MaskReg</a>。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>目的操作数与源操作数的数据类型需要保持一致。支持的数据类型为：b8、b16、b32、b64。</p><p>索引值支持的数据类型为：uint32_t。</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section177921451558"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>位于UB的地址必须32字节对齐。</li><li>源操作数和目的操作数数据类型必须相同。</li><li>index索引值必须32字节对齐，即一个索引值对应1个DataBlock。</li><li>index索引值对应的数据必须在UB有效地址范围内。</li><li>RegTensor模板参数regTrait只支持RegTraitNumOne。</li><li>index仅前8个元素有效。</li></ul><h2 id="调用示例">调用示例<span id="section642mcpsimp"></span><a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">GatherBVF</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">srcAddr</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">uint32_t</span><span class="o">*</span><span class="w"> </span><span class="n">indexAddr</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstReg</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">indexReg</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskReg</span><span class="w"> </span><span class="n">calMask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">CreateMask</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskPattern</span><span class="o">::</span><span class="n">VL8</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskReg</span><span class="w"> </span><span class="n">storeMask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">CreateMask</span><span class="o">&lt;</span><span class="n">T</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskPattern</span><span class="o">::</span><span class="n">ALL</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="p">(</span><span class="n">indexReg</span><span class="p">,</span><span class="w"> </span><span class="n">indexAddr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">GatherB</span><span class="p">(</span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcAddr</span><span class="p">,</span><span class="w"> </span><span class="n">indexReg</span><span class="p">,</span><span class="w"> </span><span class="n">calMask</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreAlign</span><span class="p">(</span><span class="n">dstAddr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">,</span><span class="w"> </span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">storeMask</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const k=a(t,[["render",e]]);export{g as __pageData,k as default};
